description.example_query:
MATCH (me:User {user_id:$uid})-[:FRIEND]->(f:User)
MATCH (f)-[r:VISITED|REVIEWED|CHECKEDIN|TIPPED]->(b:Business {business_id:$bid})
RETURN f.user_id AS friend_id, f.name AS friend_name, type(r) AS relation;

SELECT business_id, name, address, city, state, stars, review_count, categories
FROM business
WHERE city='New Orleans' AND state='LA'
  AND (
    categories LIKE '%Bar%' OR categories LIKE '%Cocktail%' OR categories LIKE '%Lounges%' OR categories LIKE '%Jazz%'
  );

/* friends who reviewed business */
MATCH (me:User {user_id:$uid})-[:FRIEND]->(f:User)-[:WROTE_REVIEW]->(r:Review)-[:REVIEWS]->(b:Business)
WHERE b.business_id IN $biz_ids
RETURN b.business_id AS business_id, collect(DISTINCT f.user_id) AS friend_reviewers;

/* elite reviewers */
MATCH (u:User)-[:WROTE_REVIEW]->(:Review)-[:REVIEWS]->(b:Business)
WHERE b.business_id IN $biz_ids AND (u.elite IS NOT NULL AND u.elite <> '')
RETURN b.business_id, collect(DISTINCT u.user_id) AS elite_reviewers;

SELECT photo_id, business_id, caption, label
FROM photo
WHERE business_id=? AND (
  lower(caption) LIKE '%entrance%' OR lower(caption) LIKE '%door%' OR lower(caption) LIKE '%stage%' OR lower(caption) LIKE '%band%' OR lower(caption) LIKE '%jazz%'
);

SELECT review_id, business_id, user_id, stars, date, text
FROM review
WHERE review_id IN ('r1','r2','r3');

